editorial:
For a candidate limit, extend each part as far as possible without exceeding it. This leaves the longest possible prefix covered after any fixed number of parts, so the scan minimizes the number of parts. If that minimum is at most k, split further to reach exactly k. Nonnegative values guarantee splitting does not raise any sum. Search between max(a) and sum(a). Time O(n log(sum(a)+1)), space O(n).
~~~
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int n,k; cin>>n>>k;
    vector<long long>a(n);
    for (auto& x:a) cin>>x;
    long long lo=*max_element(a.begin(),a.end()),hi=accumulate(a.begin(),a.end(),0LL);
    while (lo<hi) {
        long long mid=lo+(hi-lo)/2,sum=0;
        int parts=1;
        for (long long x:a) {
            if (sum+x>mid) { ++parts; sum=0; }
            sum+=x;
        }
        if (parts<=k) hi=mid;
        else lo=mid+1;
    }
    cout<<lo<<'\n';
}
